# SAH_2026/raw/phenology_overrides.csv: the free-text calendars of the SA Flora profiles (Acacia notes of Whibley & Symon, regional and
# conditional wording) that the parser misreads, read one by one (2026-11-05; ignore/jobs/sa1 review of 76 long Phenology fields). An
# override replaces all of the taxon's flowering_time / fruiting_time rows, so each taxon lists every row it keeps. Months J F M A M J J A S O N D.
import csv
P = "data/SAH_2026/raw/phenology_overrides.csv"
H = ["taxon_name", "population_region", "commonness_qualifier", "flowering_time", "fruiting_time", "description", "trait_scoring_method", "scoring_certainty"]
R = []
def row(t, fl="", fr="", reg="", q="", d="", cert=""): R.append(dict(zip(H, [t, reg, q, fl, fr, d, "", cert])))
row("Acacia calamifolia", "nnnnnnnyyyyn", q="mainly", d="Mainly in spring from August-November")
row("Acacia calamifolia", "yyyyynnnnnny", q="often", d="but can often be found sparsely flowering in summer and autumn months")
row("Acacia confluens", "nnnnnynyynnn", d="An irregular and sparsely flowering species, observed flowering m. June, August and September")
row("Acacia genistifolia", "nnnnnnnnynnn", reg="South Australia", d="Collected in flower in September")
row("Acacia genistifolia", "nnnynnnyynnn", reg="interstate", d="but interstate appearing to flower in both autumn (April) and spring (August-September)", cert="apparently")
row("Acacia genistifolia", fr="ynnnnnnnnnny", d="Ripe fruits in December-January")
row("Acacia georginae", "nnnnyyyynnnn", "nnnnnnnnyyyy", reg="Northern Territory and Queensland",
    d="Not yet collected in flower in South Australia, but in adjacent N.T. and Qld it flowers between May and August with pods from September to December")
row("Acacia halliana", "nnnnnnnyyynn", d="The species has been collected in flower between August and (principally) October")
row("Acacia halliana", "nnnnnnnnnynn", q="mainly", d="between August and (principally) October")
row("Acacia halliana", fr="nnnnnnnnnnny", d="and in pod in December")
row("Acacia helmsiana", "nnnnnyyynnnn", d="June to (principally) August, ripe pods not recorded")
row("Acacia helmsiana", "nnnnnnnynnnn", q="mainly", d="June to (principally) August")
row("Acacia jennerae", "nnyyyyyynnnn", reg="Western Australia and Northern Territory",
    d="No flowering material yet collected in South Australia but in adjacent W.Aust. and N.T. flowering between March and August")
row("Acacia mitchellii", "yynnnnnnnnny", q="mainly", d="Irregular times during the year, mainly summer months December-February")
row("Acacia mitchellii", "yyyyyyyyyyyy", q="occasionally", d="Irregular times during the year")
row("Acacia papyrocarpa", "nnnnnnnyyyyn", q="mainly", d="Irregular periods, mainly August-November")
row("Acacia praemorsa", "nnnnnnnnnyny", "nnnnnnnnnyny", d="it has been found in flower and fruit in October and again in December")
row("Acacia retinodes", "yynnnnnnnnny", q="mainly", d="Irregular periods throughout the year, but mainly summer months")
row("Acacia retinodes", "nnnnnnnnnyyy", q="usually", d="Usually October-December")
row("Acacia retinodes", "yyyyyyyyyyyy", q="occasionally", d="Irregular periods throughout the year")
row("Acacia rhodophloia", "nnnynnnnnnnn", reg="South Australia", d="A single flowering record in April, and no fruiting record")
row("Acacia rhodophloia", "nnnnnyyyyynn", "nnnnnnnnyyyn", reg="Western Australia and Northern Territory",
    d="In adjacent W.Aust. and N.T. it has been recorded in flower between June and October and pods from September to November")
row("Acacia rivalis", "nnnnyyyyyyyn", d="May-November")
row("Acacia rivalis", fr="nnnnyyyyyyyn", q="often", d="Flowers and mature pods often found on the tree together")
row("Acacia symonii", "nnnnynnynnny", d="It has been collected in flower in May, August and December")
row("Acacia symonii", fr="nnnnnnnnynnn", reg="Western Australia", d="and in pod in W.Aust. in September")
row("Acacia tenuissima", "nnnyyyyynnnn", reg="Central Australia", d="Not yet collected in flower in South Australia but flowering between April and August in Central Australia")
row("Acacia triquetra", "nnnnnnyyyynn", "nnnnnnnnnnyy", d="July to October principally September, pods ripe in November and December")
row("Acacia triquetra", "nnnnnnnnynnn", q="mainly", d="July to October principally September")
row("Amyema maidenii subsp. maidenii", "nnnnyyyyynnn", q="mainly", d="Flowers: throughout the year in response to rains, particularly May–Sep.")
row("Amyema maidenii subsp. maidenii", "yyyyyyyyyyyy", q="occasionally", d="Flowers: throughout the year in response to rains")
row("Amyema miquelii", "yyyynnnnnnnn", reg="southern areas", q="mainly", d="Flowers: in southern areas mainly late Jan.–Apr.")
row("Amyema miquelii", fr="nnnnyyyyyyyy", reg="southern areas", d="Fruits: in southern areas May–Dec.")
row("Amyema miquelii", "yyyyyyyynnny", "yyyyyyyyyyyy", reg="northern arid areas",
    d="in northern arid areas more widely throughout the year but rarely in spring. Fruits: in northern arid areas throughout the year")
row("Amyema miquelii", "nnnnnnnnyyyn", reg="northern arid areas", q="rarely", d="but rarely in spring")
row("Cannabis sativa", "yynnnnnnnnyy", q="mainly", d="Flowers: mainly Nov.–Feb.")
row("Cannabis sativa", "yyyyyyyyyyyy", q="occasionally", d="but also at most other times")
row("Cassytha peninsularis", "nnnnnnnnnynn", "nnyyyyyyyyyy", d="Flowers: from Oct. onwards; fruits start to form in March and are mostly shed by Dec.")
row("Corybas fordhamii", "nnnnnnyyynnn", d="Flowers: July-Sept.")
row("Corybas fordhamii", "nnnnnnnnynnn", reg="South Australia", d="(S.Aust. in Sept.)")
row("Corybas unguiculatus", "nnnnyyyyyynn", d="Flowers: May-Oct.")
row("Corybas unguiculatus", "nnnnnyyynnnn", reg="South Australia", d="(June-Aug. in S.Aust.)")
row("Cotyledon orbiculata var. orbiculata", "ynnnnnnnnnyy", reg="South Africa", d="its later flowering period, which is Nov.-Jan. in South Africa")
row("Daucus glochidiatus", "nnnnnnnyyyyn", d="Flowers: Aug.-Nov.")
row("Daucus glochidiatus", "yynnnnnnnnny", q="occasionally", d="occasionally (especially in shady forests) throughout the summer months")
row("Glaucium flavum", "ynnnnyyynnny", q="mainly", d="Flowers: mainly during winter and early summer")
row("Glaucium flavum", "yyyyyyyyyyyy", q="occasionally", d="but if conditions are favourable it flowers throughout the year")
row("Grevillea aquifolium", "yyynnnnnnnyy", d="Flowers: Nov.-March")
row("Grevillea aquifolium", "yyyynnnnyyyy", reg="Grampians, Victoria", d="(Sept.-April in Grampians, Vic.)")
row("Hakea repullulans", "nnnnnnnnyynn", d="Flowers: Sept.-Oct.")
row("Hakea repullulans", "nnnnnnnnyyyn", reg="Victoria", d="to Nov. in Vic.")
row("Lavandula dentata", "nnnnnyyyyyyn", q="mainly", d="Flowers: mainly June-Nov.")
row("Lavandula dentata", "yyyyyyyyyyyy", q="occasionally", d="but if conditions remain favourable flowers can be found throughout the year")
row("Lysiana exocarpi subsp. exocarpi", "yyynnnnnnnnn", "nnnyyyynnnnn", reg="southern areas", q="mainly",
    d="Flowers: in southern areas mainly Jan.–Mar. Fruits: in southern areas mainly Apr –Jul.")
row("Lysiana exocarpi subsp. exocarpi", "nnyyyyynnnnn", "nnnnnnyyynnn", reg="northern arid areas",
    d="in northern arid areas Mar.–Jul. Fruits: in northern arid areas Jul.–Sep.")
row("Picris squarrosa", "yyynnnnnnyyy", q="mainly", d="Flowers: mainly Oct.–Mar.")
row("Picris squarrosa", "nnnyynnyynnn", q="occasionally", d="some flowering outside this period (Aug.–May) in favourable conditions")
row("Ptilotus aristatus subsp. aristatus", "nnnnnnyyynnn", q="mainly", d="Flowers mainly Jul.–Sep.")
row("Ptilotus aristatus subsp. aristatus", "yyyyyyyyyyyy", q="occasionally", d="also recorded other months throughout the year")
row("Ricinus communis", "yynnnnnnnnny", reg="South Australia", d="Flowers: in summer (S.Aust.)")
row("Ricinus communis", "yyyyyyyyyyyy", reg="tropics", d="throughout the year in the tropics")
row("Stemodia viscosa", "nnnynnyyynnn", d="Flowers: April, July-Sept.")
row("Stemodia viscosa", "yyyyyyyyyyyy", reg="arid Northern Territory", d="(in arid N.T. all year)")
row("Utricularia australis", "yyyynnnnnnyy", reg="Victoria", d="Flowers (in Vic.): Nov.-April.")
w = csv.DictWriter(open(P, "w", newline=""), fieldnames=H, lineterminator="\n"); w.writeheader(); w.writerows(R)
for r in R: assert all(len(r[k]) in (0, 12) and set(r[k]) <= set("yn") for k in ("flowering_time", "fruiting_time")), r
print(len(R), "rows,", len({r["taxon_name"] for r in R}), "taxa")
